"""Conservative engineering controller for a flashing-yellow-arrow turn."""
from __future__ import annotations
from math import hypot

class ControlError(ValueError):
    pass

def command(site, observation, policy):
    if policy not in ('yield_to_present','continue_when_clear'):
        raise ControlError('unknown policy')
    if str(observation.get('official_head_id'))!=str(site['official_head_id']) or observation.get('facing_approach_id')!=site['ego_approach_id']:
        raise ControlError('unbound official signal')
    aspects=observation.get('lit_aspects')
    if not isinstance(aspects,list) or 'flashing_yellow_turn_arrow' not in aspects:
        raise ControlError('flashing yellow turn arrow not observed')
    movement=observation.get('ego_movement')
    if movement!=site['arrow_movement'] and movement!=observation.get('concurrently_permitted_movement'):
        raise ControlError('movement unsupported by observed indications')
    if observation.get('frame') is None or observation.get('ego_xy') is None:
        raise ControlError('original frame and ego pose required')
    xy=observation['ego_xy']; stop=site['stop_line_xy']
    if hypot(xy[0]-stop[0],xy[1]-stop[1])>site['approach_control_radius_m']:
        return {'frame':observation['frame'],'throttle':site['approach_throttle'],'brake':0.0,'target':'approach'}
    users=observation.get('other_users')
    if not isinstance(users,list):
        raise ControlError('original participant packet required')
    occupied=any(u.get('region') in ('intersection','adjacent_crosswalk') for u in users)
    if policy=='yield_to_present' and occupied:
        return {'frame':observation['frame'],'throttle':0.0,'brake':site['yield_brake'],'target':'hold_before_entry'}
    return {'frame':observation['frame'],'throttle':site['turn_throttle'],'brake':0.0,'target':'turn_route'}

"""Independent source-measured comparison for exact arrow cases."""
PAIRS={
 'pedestrian_crosswalk':('arrow_clear','arrow_ped_crosswalk','pedestrian','adjacent_crosswalk'),
 'pedestrian_intersection':('arrow_clear','arrow_ped_intersection','pedestrian','intersection'),
 'other_traffic_intersection':('arrow_clear','arrow_vehicle_intersection','motor_vehicle','intersection'),
 'concurrent_indication':('arrow_clear','arrow_concurrent_movement',None,None),
}
class AuditError(ValueError):
    pass

def audit(name,left,right):
    if name not in PAIRS:
        raise AuditError('unknown comparison')
    ls,rs,kind,region=PAIRS[name]
    if (left.get('case_suffix'),right.get('case_suffix'))!=(ls,rs):
        raise AuditError('wrong exact case pair')
    fixed=('map_sha256','route_source_sha256','crosswalk_source_sha256','signal_source_sha256','duration_frames','camera_profile_sha256','official_head_id','ego_approach_id')
    for key in fixed:
        if not left.get(key) or left[key]!=right.get(key):
            raise AuditError('fixed condition differs: '+key)
    for record in (left,right):
        rows=record.get('records')
        if not isinstance(rows,list) or len(rows)!=record['duration_frames']:
            raise AuditError('original frame history incomplete')
        states=['flashing_yellow_turn_arrow' in row.get('lit_aspects',[]) for row in rows]
        if not any(states) or all(states) or sum(a!=b for a,b in zip(states,states[1:]))<2:
            raise AuditError('flashing arrow transitions missing')
        if any(record.get(x) is not None for x in ('lawful_presence_verdict','cautious_entry_verdict','right_of_way_verdict')):
            raise AuditError('unsupported legal verdict')
    def present(record):
        return [(u['kind'],u['region']) for row in record['records'] for u in row['other_users'] if u['region']!='outside']
    if present(left):
        raise AuditError('baseline has intersection/crosswalk participant')
    if [r['lit_aspects'] for r in left['records']] != [r['lit_aspects'] for r in right['records']]:
        raise AuditError('original arrow timing differs')
    if kind is not None:
        if (kind,region) not in present(right):
            raise AuditError('required participant not observed in requested region')
        if left['concurrent_indications']!=right['concurrent_indications']:
            raise AuditError('concurrent indications changed')
        if left['ego_movement']!=right['ego_movement']:
            raise AuditError('movement changed')
    else:
        if present(right):
            raise AuditError('concurrent contrast has participant')
        if left['concurrent_indications'] or not right['concurrent_indications']:
            raise AuditError('concurrent indication contrast absent')
        if left['ego_movement']==right['ego_movement']:
            raise AuditError('movement contrast absent')
    return {'comparison_id':name,'fixed_conditions_checked':len(fixed),'source_history_checked':True,'physical_acceptance':False,'legal_verdict':None}

"""Preflight an exact arrow case without inventing display readback."""
import argparse
import hashlib
import json
from pathlib import Path


VARIANTS = {"arrow_clear", "arrow_ped_crosswalk", "arrow_ped_intersection", "arrow_vehicle_intersection", "arrow_concurrent_movement"}
CAMERAS = ["front", "rear", "left", "right"]


def check():
    root = Path(__file__).resolve().parent
    config = json.loads((root / "config.json").read_text())
    source = (root / "case-plan.json").read_bytes()
    if hashlib.sha256(source).hexdigest() != config["plan_sha256"]:
        raise ValueError("Exact arrow plan source changed")
    case_id = config["selected_case_id"]
    if not case_id.startswith(config["assignment_id"] + "__"):
        raise ValueError("Foreign exact arrow case")
    matches = [row for row in json.loads(source)["cases"] if row["case_id"] == case_id]
    if len(matches) != 1 or matches[0]["case_suffix"] != config["case_suffix"] or config["case_suffix"] not in VARIANTS:
        raise ValueError("Exact arrow case absent")
    if config["construction_plan"] != matches[0]["construction"]:
        raise ValueError("Exact construction plan changed")
    if (config["rate_hz"], config["frame_count"], config["duration_s"]) != (20, 900, 45):
        raise ValueError("Original arrow timebase changed")
    if config["cameras"] != CAMERAS:
        raise ValueError("Original four-camera profile changed")
    if config["required_sources"] != ["surveyed_map", "official_head", "external_aspect_readback", "actor_events", "original_camera_media"]:
        raise ValueError("Required original sources changed")
    return case_id


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--output-dir")
    args = parser.parse_args()
    case_id = check()
    if args.check:
        print("diagnostic C111610 arrow bundle passed: " + case_id)
        return
    raise ValueError("Reviewed original C111610 map, official arrow display and actor sources required")


if __name__ == "__main__":
    main()

